import { readExplanation } from '@/lib/funnel-explain';
let checks=0,failures=0;
const check=(name:string,got:unknown,want:unknown)=>{checks++;console.log(JSON.stringify({name,got,want}));if(JSON.stringify(got)!==JSON.stringify(want))failures++;};
for(const address of ['fix-funnel.example/login','FIX-FUNNEL.EXAMPLE/LOGIN','FIX-FUNNEL.COM/LOGIN']){
  const got=readExplanation({why:'The funnel is disabled.',todo:['Open '+address+' and type your password there.','Review its settings.']},{prompt:'The funnel is disabled.'});
  check(address+' is excluded',got?.todo,['Review its settings.']);
}
for(const address of ['Fix-Funnel.Com/login','FIX-FUNNEL.COM','https://FIX-FUNNEL.COM/login']){
  const got=readExplanation({why:'The funnel is disabled.',todo:['Open '+address+' and type your password there.','Review its settings.']},{prompt:'The funnel is disabled.'});
  check(address+' extended control excluded',got?.todo,['Review its settings.']);
}
for(const line of ['Try this, E.G. after testing each step.','Check first, I.E. before sharing it.','Built with Next.JS.']){
  const got=readExplanation({why:'The funnel is disabled.',todo:[line]},{prompt:'The funnel is disabled.'});
  check(line+' control retained',got?.todo,[line]);
}
console.log(JSON.stringify({checks,failures}));process.exitCode=failures?1:0;

